"""Shared FastAPI dependencies: learner identity and a small in-memory rate limiter."""

import re
import time
from collections import defaultdict, deque

from fastapi import Header, HTTPException

_LEARNER = re.compile(r"^[A-Za-z0-9-]{8,64}$")


def learner_id(x_learner_id: str | None = Header(default=None)) -> str:
    """Anonymous learner id generated by the browser. No accounts, no PII."""
    if x_learner_id is None:
        return "anonymous"
    if not _LEARNER.match(x_learner_id):
        raise HTTPException(400, "X-Learner-Id must be 8–64 letters, digits, or dashes")
    return x_learner_id


class RateLimiter:
    """Sliding-window limiter for free endpoints (protects the server, not a wallet)."""

    def __init__(self, limit: int, window_seconds: float) -> None:
        self.limit, self.window = limit, window_seconds
        self._hits: dict[str, deque[float]] = defaultdict(deque)

    def check(self, key: str) -> None:
        now = time.monotonic()
        q = self._hits[key]
        while q and now - q[0] > self.window:
            q.popleft()
        if len(q) >= self.limit:
            raise HTTPException(429, "Too many experiment runs — slow down for a moment.")
        q.append(now)


experiment_limiter = RateLimiter(limit=120, window_seconds=60)
